class Buffer
{
public:
    explicit Buffer(int value)
        : data_(new int(value))
    {
    }

    ~Buffer()
    {
        delete data_;
    }

    int value() const
    {
        return *data_;
    }

    void setValue(int value)
    {
        *data_ = value;
    }

private:
    int* data_;
};

reference_solution:
class Buffer
{
public:
    explicit Buffer(int value)
        : data_(new int(value))
    {
    }

    Buffer(const Buffer& other)
        : data_(new int(*other.data_))
    {
    }

    ~Buffer()
    {
        delete data_;
    }

    int value() const
    {
        return *data_;
    }

    void setValue(int value)
    {
        *data_ = value;
    }

private:
    int* data_;
};
